package com.bnfix.ubm.domains.partnership;
import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface PartnershipRepository extends JpaRepository<Partnership,Long> { List<Partnership> findByClientCompanyId(Long id); List<Partnership> findByBenefitId(Long id); List<Partnership> findByStatus(PartnershipStatus s); List<Partnership> findByClientCompanyIdAndStatus(Long id,PartnershipStatus s); boolean existsByClientCompanyIdAndBenefitId(Long c,Long b); Optional<Partnership> findByClientCompanyIdAndBenefitIdAndStatus(Long c,Long b,PartnershipStatus s); @Query("select p from Partnership p join fetch p.clientCompany join fetch p.benefit b join fetch b.provider where p.id=:id") Optional<Partnership> findByIdWithProvider(@Param("id") Long id); @Query("select p from Partnership p join fetch p.clientCompany join fetch p.benefit b join fetch b.provider where b.provider.id=:id and p.status=:status order by p.createdAt") List<Partnership> findPendingByProvider(@Param("id") Long id,@Param("status") PartnershipStatus status); default List<Partnership> findPendingByProvider(Long id){return findPendingByProvider(id,PartnershipStatus.PENDING);} default boolean existsActivePartnership(Long c,Long b){return existsByClientCompanyIdAndBenefitIdAndStatus(c,b,PartnershipStatus.ACTIVE);} boolean existsByClientCompanyIdAndBenefitIdAndStatus(Long c,Long b,PartnershipStatus s); @Modifying @Query("update Partnership p set p.status=:disabled where p.status in (:pending,:active) and (p.clientCompany.id=:id or p.benefit.provider.id=:id)") int disableByCompanyId(@Param("id") Long id,@Param("disabled") PartnershipStatus disabled,@Param("pending") PartnershipStatus pending,@Param("active") PartnershipStatus active); default int disableByCompanyId(Long id){return disableByCompanyId(id,PartnershipStatus.DISABLED,PartnershipStatus.PENDING,PartnershipStatus.ACTIVE);} }
